// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // keep the deposit in a wide admissible domain: positive ether amounts
        amount = bound(amount, 1, 1e30);
        vm.deal(address(this), amount);

        // fund c through its payable fallback
        (bool okDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okDeposit);
        assertTrue(address(c).balance == amount);

        // owner (deployer = this test contract) withdraws everything
        c.withdrawAll();

        // rule: withdrawAll always transfers the ENTIRE contract balance out
        assertTrue(address(c).balance == 0);
    }
}
